    Bug 2048163 - Attempting to fix browser_oAuthGranularScopes.js by awaiting the OAuth dialog handling in browser_oAuthGranularScopes.js. r=darktrojan

    subtest() called expectOAuthDialog() fire-and-forget, so
    OAuth2TestUtils.promiseOAuthWindow()'s "window unloaded while we were waiting for
    the browser to load" rejection became an uncaught rejection, failing the test
    and cascading into a timeout. Every non-flaky OAuth test that uses
    promiseOAuthWindow (browser_verifyConfig.js, browser_oAuth2Window.js,
    browser_accountHubOAuth.js) captures its promise before triggering the flow and
    awaits it. Do the same here: capture the expectOAuthDialog() promise and await
    it, so the dialog handling is coordinated with the verify flow and any error is
    surfaced instead of thrown into the void.

    Differential Revision: https://phabricator.services.mozilla.com/D310620

diff --git a/mail/components/accountcreation/test/browser/browser_oAuthGranularScopes.js b/mail/components/accountcreation/test/browser/browser_oAuthGranularScopes.js
index 7a0274202d0..d67c7bbd5b1 100644
--- a/mail/components/accountcreation/test/browser/browser_oAuthGranularScopes.js
+++ b/mail/components/accountcreation/test/browser/browser_oAuthGranularScopes.js
@@ -67,7 +67,7 @@ async function subtest(grantedScope, expectFailure) {
     emailAddress: "test@test.test",
   };

-  expectOAuthDialog(grantedScope);
+  const oAuthPromise = expectOAuthDialog(grantedScope);
   const abortController = new AbortController();
   const verifier = new ConfigVerifier(window.msgWindow, abortController.signal);
   const verifyPromise = verifier.verifyConfig(config);
@@ -101,6 +101,10 @@ async function subtest(grantedScope, expectFailure) {
     });
   }

+  // Coordinate with the OAuth dialog handling and surface any error from it
+  // instead of leaving it as an uncaught rejection.
+  await oAuthPromise;
+
   // Wait for the OAuth module to record telemetry, which signals that the
   // token exchange has fully completed.
   await TestUtils.waitForCondition(
